/* =====================================================================================
   CinemaWebDB — DỮ LIỆU MẪU (gọn, sát thực tế, deterministic)
   --------------------------------------------------------------------------------------
   Chạy SAU file schema `CinemaWebDB_v2.sql`. File này KHÔNG tạo bảng, chỉ chèn dữ liệu.

   MỐC THỜI GIAN LÀ TƯƠNG ĐỐI — chạy ngày nào cũng có dữ liệu hợp lệ:
     @Mon = thứ Hai của TUẦN HIỆN TẠI. Suất chiếu trải từ thứ Tư tuần trước (@Mon-5)
     đến thứ Ba tuần sau (@Mon+8) nên luôn có suất đã chiếu, đang chiếu và sắp chiếu.
     Trạng thái Showtimes/Tickets được gán ở CUỐI file bằng UPDATE so với GETDATE().

   QUY ƯỚC GIÁ (khớp Application/Services/PricingService.cs):
     giá vé = giá cơ bản (theo phim, không có thì lấy cấu hình chung)
            + phụ thu loại phòng + phụ thu khung giờ + phụ thu loại ghế
     Phụ thu khung giờ KHÔNG cộng dồn — chỉ lấy quy tắc có [priority] cao nhất khớp được.
     final_amount = total_amount - discount_amount + vat_amount   (VAT 8%)

   DANH SÁCH PHIM LÀ PHIM CÓ THẬT — đối chiếu lịch chiếu CGV / Moveek / rapchieuphim
   ngày 27/07/2026 (tên, đạo diễn, diễn viên, thời lượng, phân loại tuổi đều là số liệu thật).
   [release_date] quy từ ngày khởi chiếu thật thành số ngày lệch so với @Today, ví dụ
   The Odyssey khởi chiếu 17/07/2026 -> DATEADD(DAY,-10,@Today). Nhãn tuổi dùng bộ
   P/C13/C16/C18 của AgeRatingPolicy.DisplayOrder (quy đổi T13->C13, T16->C16, T18->C18).

   ẢNH PHIM LƯU NGAY TRÊN SERVER, không phụ thuộc CDN bên ngoài. DB chỉ lưu TÊN FILE TRẦN,
   Application/Common/MediaUrl.cs sẽ tự ghép tiền tố:
     [poster_url] = "<slug>.webp"        -> wwwroot/images/<slug>.webp          (400x600)
     [banner_url] = "banner_<slug>.webp" -> wwwroot/banner/banner_<slug>.webp   (800x420)
   3 phim không có ảnh ngang thì [banner_url] = NULL — view tự lùi về dùng poster.

   [trailer_url] là ID video YouTube THẬT dạng watch?v=<11 ký tự>, đã xác minh bằng oEmbed.
   Views/Public/Movies/Details.cshtml bắt regex [?&]v=([A-Za-z0-9_-]{11}) để nhúng iframe —
   link tìm kiếm hoặc chuỗi khác 11 ký tự sẽ KHÔNG phát được video.

   File lưu UTF-8 CÓ BOM — mở bằng SSMS / VS Code đều đúng tiếng Việt.
   Chạy bằng dòng lệnh: sqlcmd -S <server> -d CinemaWebDB -I -i CinemaWebDB_SeedData.sql
   (bắt buộc có -I: các FILTERED INDEX trong schema đòi QUOTED_IDENTIFIER ON)

   TÀI KHOẢN ĐĂNG NHẬP — mật khẩu chung: Admin@123
     admin@cinemaweb.vn | manager1..2@cinemaweb.vn | staff1..4@cinemaweb.vn
     Khách hàng: xem cột [email] bảng [Users], cùng mật khẩu Admin@123.
   ===================================================================================== */
USE CinemaWebDB;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;   -- bất kỳ lỗi nào -> rollback toàn bộ, không để lại dữ liệu chèn dở
BEGIN TRANSACTION;

DECLARE @Now   DATETIME = GETDATE();
DECLARE @Today DATETIME = CAST(CAST(@Now AS DATE) AS DATETIME);
-- 1900-01-01 là thứ Hai -> công thức không phụ thuộc @@DATEFIRST hay ngôn ngữ phiên làm việc
DECLARE @Mon   DATETIME = DATEADD(DAY, -(DATEDIFF(DAY,'19000101',@Now) % 7), @Today);

-- Roles: 4 dòng — 4 vai trò cố định theo CK_Roles_Name

-- Users: 27 dòng — 1 quản trị, 2 quản lý, 4 nhân viên, 20 khách (mật khẩu đều là Admin@123)

-- Cinemas: 1 dòng — dự án chỉ vận hành 1 rạp duy nhất — xem RoomService.GetSingleCinemaAsync

-- Room_Types: 4 dòng — 4DX chưa có phòng thực tế — giữ lại để thử cấu hình phụ thu loại phòng

-- Rooms: 6 dòng — 6 phòng, trong đó 1 phòng đang bảo trì để thử luồng khoá phòng

-- Seat_Types: 4 dòng — Couple = ghế đôi, ngồi 2 người và chiếm 2 cột trên sơ đồ

-- Seats: 283 dòng — 283 ghế; 3 ghế Broken để thử hiển thị ghế hỏng trên sơ đồ

-- Genres: 11 dòng — 11 thể loại

-- Movies: 13 dòng — phim CÓ THẬT theo lịch chiếu CGV/Moveek ngày 27/07/2026: 8 Đang chiếu, 2 Sắp chiếu, 1 Đặc biệt, 2 Ngừng chiếu

-- Movie_Genres: 26 dòng — mỗi phim gắn 2 thể loại

-- Showtimes: 122 dòng — từ @Mon-5 (thứ Tư tuần trước) đến @Mon+8 (thứ Ba tuần sau); 2 suất bị huỷ. Trạng thái thật gán bằng UPDATE ở cuối file

-- Food_Beverages: 8 dòng — 8 món, trong đó 1 món đang hết hàng

-- Promotions: 5 dòng — 4 mã còn hiệu lực + 1 mã đã hết hạn

-- VAT: 2 dòng — vat_rate lưu dạng THẬP PHÂN (0.08 = 8%) theo CK_VAT_rate

-- Price_Base_Configs: 4 dòng — 1 giá chung + 3 giá riêng cho bom tấn / suất chiếu đặc biệt

-- Price_Seat_Configs: 4 dòng — phụ thu theo loại ghế

-- Price_Room_Type_Configs: 4 dòng — phụ thu theo loại phòng

-- Price_Time_Configs: 3 dòng — suất tối (priority 2) ĐÈ quy tắc cuối tuần (priority 1) — không cộng dồn

-- Bookings: 179 dòng — 179 đơn: 133 Online / 46 tại quầy

-- Tickets: 389 dòng — 389 vé; scan_by/scanned_at được gán ở cuối file cho suất đã chiếu

-- Booking_Foods: 75 dòng — bắp nước mua kèm, lưu giá tại thời điểm đặt

-- Payments: 171 dòng — Cash/Transfer = quầy (source Counter), VNPay/VietQR = online; đơn 0đ -> Free

-- Email_Logs: 128 dòng — email xác nhận vé + 2 email gửi lỗi + 1 email đang chờ gửi

-- Reward_Point_History: 154 dòng — cột [Users].[reward_points] bằng đúng tổng điểm của bảng này

-- Reviews: 28 dòng — chỉ khách ĐÃ mua vé của suất đã chiếu mới có đánh giá

-- Seat_Holds: 6 dòng — 3 lệnh giữ ghế ĐANG hiệu lực (hết hạn sau @Now 7 phút) + lệnh đã nhả / đã chuyển thành vé

-- Audit_Logs: 14 dòng — tên action khớp với chuỗi mà Controller/Service đang ghi

-- ShowtimeIncidents: 2 dòng — sự cố ở suất đã chiếu, kèm mã khuyến mãi đền bù

-- SystemConfig: 6 dòng — cấu hình vận hành hệ thống

-- =====================================================================================
-- HẬU XỬ LÝ: gán các giá trị phụ thuộc THỜI ĐIỂM CHẠY (mọi câu đều chạy lại được)
-- =====================================================================================

-- 1) Trạng thái suất chiếu theo mốc hiện tại (giữ nguyên các suất đã bị huỷ)
UPDATE [Showtimes]
SET [status] = CASE WHEN [end_time]   <= @Now THEN N'Completed'
                    WHEN [start_time] <= @Now THEN N'Live'
                    ELSE N'Scheduled' END
WHERE [status] <> N'Cancelled';

-- 2) Đơn của suất tương lai xa không thể được tạo sau thời điểm hiện tại -> rải đều về
--    10 ngày gần nhất (để biểu đồ doanh thu theo ngày không bị dồn cục vào 1-2 ngày).
--    14369 nguyên tố cùng nhau với 14400 nên (rn * 14369) % 14400 duyệt hết mọi số dư.
;WITH b AS (
    SELECT [created_at], ROW_NUMBER() OVER (ORDER BY [id]) AS rn
    FROM [Bookings] WHERE [created_at] > @Now
)
UPDATE b SET [created_at] = DATEADD(MINUTE, -(30 + (rn * 14369 % 14400)), @Now);

-- 3) Đơn luôn phải được tạo TRƯỚC giờ chiếu
UPDATE b
SET b.[created_at] = DATEADD(MINUTE, -45, s.[start_time])
FROM [Bookings] b
JOIN [Showtimes] s ON s.[id] = b.[showtime_id]
WHERE b.[created_at] >= s.[start_time];

-- 4) Đồng bộ mốc thời gian của thanh toán / email / lịch sử điểm theo [Bookings].[created_at]
UPDATE p SET p.[paid_at] = DATEADD(MINUTE, 3, b.[created_at])
FROM [Payments] p JOIN [Bookings] b ON b.[id] = p.[booking_id];

UPDATE e SET e.[created_at] = DATEADD(MINUTE, 5, b.[created_at]),
            e.[sent_at]    = CASE WHEN e.[status] = N'Sent' THEN DATEADD(MINUTE, 6, b.[created_at]) END
FROM [Email_Logs] e JOIN [Bookings] b ON b.[id] = e.[booking_id];

UPDATE r SET r.[created_at] = DATEADD(MINUTE, 4, b.[created_at])
FROM [Reward_Point_History] r JOIN [Bookings] b ON b.[id] = r.[booking_id];

-- 5) Vé của suất ĐÃ CHIẾU coi như đã soát (chừa ~10% vé khách không đến, vẫn ở 'Booked')
;WITH t AS (
    SELECT tk.[status], tk.[scan_by], tk.[scanned_at], s.[start_time],
           ROW_NUMBER() OVER (ORDER BY tk.[id]) AS rn
    FROM [Tickets] tk
    JOIN [Showtimes] s ON s.[id] = tk.[showtime_id]
    JOIN [Bookings]  b ON b.[id] = tk.[booking_id]
    WHERE s.[end_time] <= @Now AND b.[payment_status] = N'Paid'
      AND tk.[status] IN (N'Booked', N'Printed')
)
UPDATE t
SET [status]     = N'Checked-in',
    [scan_by]    = CASE rn % 4 WHEN 0 THEN '00000000-0000-0000-0002-00000000000b'
                                WHEN 1 THEN '00000000-0000-0000-0002-00000000000c'
                                WHEN 2 THEN '00000000-0000-0000-0002-00000000000d'
                                ELSE        '00000000-0000-0000-0002-00000000000e' END,
    [scanned_at] = DATEADD(MINUTE, -8, [start_time])
WHERE rn % 10 <> 0;   -- cứ 10 vé chừa 1 vé khách không đến

COMMIT TRANSACTION;
GO

-- Kiểm tra số bản ghi sau khi chèn
