INSERT INTO [Movies] ([id],[title],[slug],[description],[trailer_url],[poster_url],[banner_url],[director],[cast_members],[language],[subtitle],[duration_minutes],[release_date],[age_rating],[status],[created_at]) VALUES
('00000000-0000-0000-0008-000000000001',N'The Odyssey','the-odyssey',N'Thiên anh hùng ca thần thoại của Christopher Nolan, quay toàn bộ bằng máy IMAX, kể hành trình hồi hương đầy hiểm nguy của Odysseus sau cuộc chiến thành Troy.','https://www.youtube.com/watch?v=Mzw2ttJD2qQ','the-odyssey.webp','banner_the-odyssey.webp',N'Christopher Nolan',N'Matt Damon, Tom Holland, Zendaya, Anne Hathaway, Lupita Nyong''o',N'Tiếng Anh',N'Tiếng Việt',173,DATEADD(DAY,-10,@Today),'C16',N'Now Showing',DATEADD(DAY,-40,@Today)),
('00000000-0000-0000-0008-000000000002',N'Minions & Quái Vật','minions-quai-vat',N'Nhóm Minions chinh phục Hollywood rồi vô tình thả lũ quái vật ra thế giới, và phải bắt tay nhau dọn lại mớ hỗn loạn do chính mình gây ra.','https://www.youtube.com/watch?v=HpDHFqMykpA','minions-quai-vat.webp','banner_minions-quai-vat.webp',N'Pierre Coffin',N'Lồng tiếng: Pierre Coffin',N'Tiếng Anh',N'Tiếng Việt',90,DATEADD(DAY,-26,@Today),'P',N'Now Showing',DATEADD(DAY,-56,@Today)),
('00000000-0000-0000-0008-000000000003',N'Câu Chuyện Đồ Chơi 5','cau-chuyen-do-choi-5',N'Những món đồ chơi thân quen trở lại, lần này đối đầu với công nghệ để giữ lấy niềm vui tuổi thơ.','https://www.youtube.com/watch?v=MGAr2MqzaF8','cau-chuyen-do-choi-5.webp','banner_cau-chuyen-do-choi-5.webp',N'Andrew Stanton',N'Lồng tiếng: Tom Hanks, Tim Allen, Joan Cusack, Tony Hale',N'Tiếng Anh',N'Tiếng Việt',102,DATEADD(DAY,-38,@Today),'P',N'Now Showing',DATEADD(DAY,-68,@Today)),
('00000000-0000-0000-0008-000000000004',N'Moana (Live Action)','moana-live-action',N'Bản người đóng của hành trình Moana đáp lại tiếng gọi đại dương, cùng á thần Maui ra khơi khôi phục sự thịnh vượng cho hòn đảo quê hương.','https://www.youtube.com/watch?v=Ck-AZfdQr8c','moana-live-action.webp','banner_moana-live-action.webp',N'Thomas Kail',N'Catherine Laga''aia, Dwayne Johnson, Rena Owen, John Tui',N'Tiếng Anh',N'Tiếng Việt',116,DATEADD(DAY,-17,@Today),'P',N'Now Showing',DATEADD(DAY,-47,@Today)),
('00000000-0000-0000-0008-000000000005',N'Quỷ Bắt Hồn','quy-bat-hon',N'Một gia đình bình thường dần bị vây bủa bởi những hiện tượng siêu nhiên, nơi nỗi sợ không chỉ để cảm nhận mà còn nghe thấy và gọi được tên.','https://www.youtube.com/watch?v=3clOkQ5kQAY','quy-bat-hon.webp','banner_quy-bat-hon.webp',N'Bùi Văn Hải',N'Quang Tuấn, Đinh Y Nhung, La Thành, Sỹ Toàn, Uy Trần',N'Tiếng Việt',N'Không',103,DATEADD(DAY,-17,@Today),'C16',N'Now Showing',DATEADD(DAY,-47,@Today)),
('00000000-0000-0000-0008-000000000006',N'Thám Tử Lừng Danh Conan: Thiên Thần Sa Ngã Trên Xa Lộ','conan-thien-than-sa-nga-tren-xa-lo',N'Conan và nhóm bạn tới Yokohama dự lễ hội mô tô, rồi bị cuốn vào vụ án bí ẩn quanh "Quái Xế Đen" và chiếc mô tô công nghệ cao mang tên Angel.','https://www.youtube.com/watch?v=AgTzZDGYghA','conan-thien-than-sa-nga-tren-xa-lo.webp','banner_conan-thien-than-sa-nga-tren-xa-lo.webp',N'Takahiro Hasui',N'Minami Takayama, Wakana Yamazaki, Rikiya Koyama, Miyuki Sawashiro',N'Tiếng Nhật',N'Tiếng Việt',109,DATEADD(DAY,-3,@Today),'C13',N'Now Showing',DATEADD(DAY,-33,@Today)),
('00000000-0000-0000-0008-000000000007',N'Công Viên Giải Thoát','cong-vien-giai-thoat',N'Nhóm học sinh quen thói bắt nạt người bạn tự kỷ đưa cậu tới công viên nước bỏ hoang bị đồn có ma, và trò đùa vượt khỏi tầm kiểm soát.','https://www.youtube.com/watch?v=sc6qMJdUY6M','cong-vien-giai-thoat.webp','banner_cong-vien-giai-thoat.webp',N'Phontharis Chotkijsadarsopon',N'Nattawat Jirochtikul, Yongsin Wongpanitnont, Jaturawit Cheawprasit',N'Tiếng Thái',N'Tiếng Việt',111,DATEADD(DAY,-3,@Today),'C16',N'Now Showing',DATEADD(DAY,-33,@Today)),
('00000000-0000-0000-0008-000000000008',N'Đêm Truy Sát','dem-truy-sat',N'Một nữ cựu binh đơn thương độc mã lần theo đường dây buôn người sau khi con gái duy nhất của cô bị bắt cóc.','https://www.youtube.com/watch?v=PvbCXQ5yzXI','dem-truy-sat.webp','banner_dem-truy-sat.webp',N'Adrian Grunberg',N'Milla Jovovich, Matthew Modine, Isabel Myers, D. B. Sweeney',N'Tiếng Anh',N'Tiếng Việt',91,DATEADD(DAY,-10,@Today),'C18',N'Now Showing',DATEADD(DAY,-40,@Today)),
('00000000-0000-0000-0008-000000000009',N'Đừng Đốt','dung-dot',N'Suất chiếu đặc biệt nhân kỷ niệm Ngày Thương binh – Liệt sĩ 27/7: câu chuyện cuốn nhật ký của bác sĩ Đặng Thùy Trâm được người lính bên kia chiến tuyến gìn giữ suốt 35 năm.','https://www.youtube.com/watch?v=0ydYmbQxfjQ','dung-dot.webp','banner_dung-dot.webp',N'Đặng Nhật Minh',N'Minh Hương, Michael Jarmus, Diễm Lộc, Patrick T. McGowan',N'Tiếng Việt',N'Tiếng Anh',105,DATEADD(DAY,-6297,@Today),'C13',N'Special',DATEADD(DAY,-6327,@Today)),
('00000000-0000-0000-0008-00000000000a',N'Người Nhện: Khởi Đầu Mới','nguoi-nhen-khoi-dau-moi',N'Peter Parker làm lại từ đầu trong một New York không còn ai nhớ mình là ai, đối đầu với những mối đe doạ tăm tối hơn bao giờ hết.','https://www.youtube.com/watch?v=-aUE6APXrc0','nguoi-nhen-khoi-dau-moi.webp',NULL,N'Destin Daniel Cretton',N'Tom Holland, Zendaya, Sadie Sink, Jacob Batalon, Jon Bernthal, Mark Ruffalo',N'Tiếng Anh',N'Tiếng Việt',144,DATEADD(DAY,4,@Today),'C13',N'Coming Soon',DATEADD(DAY,-26,@Today)),
('00000000-0000-0000-0008-00000000000b',N'Avengers: Doomsday','avengers-doomsday',N'Các siêu anh hùng từ ba vũ trụ khác nhau bị đẩy vào thế đối đầu sinh tử trước hiểm hoạ mang tên Doctor Doom.','https://www.youtube.com/watch?v=sG1gruO7prQ','avengers-doomsday.webp','banner_avengers-doomsday.webp',N'Anthony Russo, Joe Russo',N'Robert Downey Jr., Chris Evans, Chris Hemsworth, Pedro Pascal, Florence Pugh, Vanessa Kirby',N'Tiếng Anh',N'Tiếng Việt',165,DATEADD(DAY,144,@Today),'C13',N'Coming Soon',DATEADD(DAY,114,@Today)),
('00000000-0000-0000-0008-00000000000c',N'Mùi Cỏ Cháy','mui-co-chay',N'Bốn sinh viên Hà Nội xếp bút nghiên lên đường, đi qua 81 ngày đêm bảo vệ Thành cổ Quảng Trị năm 1972 — chuyển thể từ nhật ký "Mãi mãi tuổi 20".','https://www.youtube.com/watch?v=9ecytf-YUKY','mui-co-chay.webp',NULL,N'Nguyễn Hữu Mười',N'Nguyễn Năng Tùng, Lê Văn Thơm, Tô Tuấn Dũng',N'Tiếng Việt',N'Không',92,DATEADD(DAY,-5336,@Today),'C13',N'Stopped',DATEADD(DAY,-5366,@Today)),
('00000000-0000-0000-0008-00000000000d',N'Mẹ Ơi Về Nhà','me-oi-ve-nha',N'Chàng trai lớn lên ở Hàn Quốc đưa tro cốt người mẹ nuôi người Việt về quê theo di nguyện, và gặp một cô ca sĩ trẻ trên hành trình tìm lại cội nguồn.','https://www.youtube.com/watch?v=cIUqTFNABJ4','me-oi-ve-nha.webp',NULL,N'Yun Byung Ki',N'Lee Yi Kyung, Hoàng Yến Chibi, Choi Daniel, Minh Hà',N'Tiếng Việt - Tiếng Hàn',N'Tiếng Việt',98,DATEADD(DAY,-17,@Today),'C16',N'Stopped',DATEADD(DAY,-47,@Today));
